const d = phi.recall("$step8");
const items = d.items.map(i => ({ t: i.title, p: i.priceText.slice(0, 40), href: i.href }));
// find cheese pizza candidates with a price in 5-10
const cand = items.filter(i => /cheese/i.test(i.t) && /pizza/i.test(i.t));
const parsed = cand.map(i => { const m = i.p.match(/\$(\d+\.\d{2})/); return { t: i.t, price: m ? Number(m[1]) : null, p: i.p, href: i.href }; });
