const vis = phi.js(() => {
  const els = Array.from(document.querySelectorAll("[data-test^='facet-button-']"));
  return els.map(e => {
    const r = e.getBoundingClientRect();
    const cs = getComputedStyle(e);
    return { t: e.getAttribute('data-test'), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), disp: cs.display, vis: cs.visibility };
  });
});
return vis;

// reveal the hidden Price facet by scrolling the facet carousel to the right
const r = phi.js(() => {
  const btn = Array.from(document.querySelectorAll("[data-test='facet-button-Price']")).find(e => e.getBoundingClientRect().width > 0);
  if (!btn) return { err: 'no visible-size price button' };
  let el = btn.parentElement;
  let scrolled = false;
  while (el && el !== document.body) {
    if (el.scrollWidth > el.clientWidth + 5) {
      el.scrollLeft = el.scrollWidth;
      scrolled = true;
      break;
    }
    el = el.parentElement;
  }
  const r0 = btn.getBoundingClientRect();
  return { scrolled, x: Math.round(r0.x), y: Math.round(r0.y), w: Math.round(r0.width), tag: el ? el.tagName + '.' + (el.className || '').toString().slice(0, 60) : null };
});
phi.sleep(800);
const after = phi.js(() => {
  const btn = Array.from(document.querySelectorAll("[data-test='facet-button-Price']")).find(e => e.getBoundingClientRect().width > 0);
  if (!btn) return null;
  const r0 = btn.getBoundingClientRect();
  const cx = r0.x + r0.width / 2, cy = r0.y + r0.height / 2;
  const top = document.elementFromPoint(cx, cy);
  return { x: Math.round(r0.x), y: Math.round(r0.y), w: Math.round(r0.width), inView: cx > 0 && cx < innerWidth && cy > 0 && cy < innerHeight, topIsButton: !!(top && btn.contains(top)), topTest: top ? top.getAttribute('data-test') : null };
});
return { r, after };

