// Read the whole results grid: every card's title + price text
const data = phi.js(() => {
  const t = document.body.innerText;
  const m = t.match(/([\d,]+)\s*results/i);
  const links = [...document.querySelectorAll('a[href*="/p/"]')];
  const out = [];
  const seen = new Set();
  for (const a of links) {
    const href = a.getAttribute('href') || '';
    const idm = href.match(/\/p\/([^/?#]+)/);
    const key = idm ? idm[1] : href;
    const txt = (a.innerText || '').replace(/\s+/g, ' ').trim();
    const label = (a.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
    if (!txt && !label) continue;
    if (seen.has(key + '|' + txt)) continue;
    seen.add(key + '|' + txt);
    out.push({ key, txt: txt.slice(0, 220), label: label.slice(0, 160) });
  }
  return { count: m ? m[1] : null, n: out.length, out };
});
phi.keep('rawcards', data);
return { count: data.count, n: data.n, sample: data.out.slice(0, 12) };
